PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS tenants(id INTEGER PRIMARY KEY, name TEXT NOT NULL, is_demo INTEGER NOT NULL DEFAULT 0, expires_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,tenant_id INTEGER NOT NULL REFERENCES tenants(id),name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password TEXT NOT NULL,is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0,1)),role TEXT NOT NULL CHECK(role IN ('owner','operator','viewer')),created_at TEXT NOT NULL,UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS items(id INTEGER PRIMARY KEY,tenant_id INTEGER NOT NULL REFERENCES tenants(id),sku TEXT NOT NULL,name TEXT NOT NULL,unit TEXT NOT NULL DEFAULT 'units',on_hand INTEGER NOT NULL DEFAULT 0 CHECK(typeof(on_hand)='integer' AND on_hand BETWEEN 0 AND 1000000),reserved INTEGER NOT NULL DEFAULT 0 CHECK(typeof(reserved)='integer' AND reserved BETWEEN 0 AND on_hand),reorder_level INTEGER NOT NULL DEFAULT 5 CHECK(reorder_level BETWEEN 0 AND 1000000),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(tenant_id,sku),UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS reservations(id INTEGER PRIMARY KEY,tenant_id INTEGER NOT NULL REFERENCES tenants(id),item_id INTEGER NOT NULL REFERENCES items(id),quantity INTEGER NOT NULL CHECK(typeof(quantity)='integer' AND quantity BETWEEN 1 AND 1000000),reference TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('active','released','fulfilled')),created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,closed_at TEXT,UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,item_id) REFERENCES items(tenant_id,id),FOREIGN KEY(tenant_id,created_by) REFERENCES users(tenant_id,id));
CREATE TABLE IF NOT EXISTS movements(id INTEGER PRIMARY KEY,tenant_id INTEGER NOT NULL REFERENCES tenants(id),item_id INTEGER NOT NULL REFERENCES items(id),reservation_id INTEGER REFERENCES reservations(id),actor_id INTEGER NOT NULL REFERENCES users(id),kind TEXT NOT NULL CHECK(kind IN ('receipt','reservation','release','fulfilment')),quantity INTEGER NOT NULL CHECK(quantity>0),on_hand_delta INTEGER NOT NULL,reserved_delta INTEGER NOT NULL,on_hand_after INTEGER NOT NULL,reserved_after INTEGER NOT NULL,reference TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(tenant_id,item_id) REFERENCES items(tenant_id,id),FOREIGN KEY(tenant_id,actor_id) REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,reservation_id) REFERENCES reservations(tenant_id,id));
CREATE TABLE IF NOT EXISTS commands(id INTEGER PRIMARY KEY,tenant_id INTEGER NOT NULL REFERENCES tenants(id),request_key TEXT NOT NULL,fingerprint TEXT NOT NULL,result_id INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(tenant_id,request_key));
CREATE TABLE IF NOT EXISTS invitations(id INTEGER PRIMARY KEY,tenant_id INTEGER NOT NULL REFERENCES tenants(id),email TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('operator','viewer')),token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,accepted_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits(id TEXT PRIMARY KEY,window_start INTEGER NOT NULL,attempts INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS items_tenant ON items(tenant_id);
CREATE INDEX IF NOT EXISTS reservations_tenant ON reservations(tenant_id,status);
CREATE INDEX IF NOT EXISTS movements_tenant ON movements(tenant_id,id);
CREATE TRIGGER IF NOT EXISTS movements_no_update BEFORE UPDATE ON movements BEGIN SELECT RAISE(ABORT,'Stock movements are append-only.'); END;
CREATE TRIGGER IF NOT EXISTS movements_no_delete BEFORE DELETE ON movements BEGIN SELECT RAISE(ABORT,'Stock movements are append-only.'); END;
